async function navigationHost(){
 const e=environment(),c=capability(e);await c.load();for(const note of ['First Keep','Second Keep'])await c.saveKeep({kind:'full',note,images:[{...fixture,id:note+'-image'}]});let closed=0;const render=sheet(e,'card-one',()=>closed++);render();await flush();e.reduce(false);return{e,render,closed:()=>closed};
}
const incoming=t=>nodes(t).find(n=>n.props?.testID==='keeps-incoming-content');
function keepRows(t){const list=nodes(t).find(n=>n.type==='FlatList');return list.props.data.filter(r=>r.record).map(item=>({id:item.record.id,press:list.props.renderItem({item}).props.onPress}));}
