test('M3-B dirty Cancel keeps every note until consent; confirmation itself does not trigger return motion',async()=>{
 const h=addKeepHarness();control(h.parent(),'Note').props.onPress();h.e.reduce(false);h.editor().props.keepsContentMotion.onShow();control(h.editor(),'Keep note').props.onChangeText('Keep this draft');control(h.editor(),'Cancel Keep').props.onPress();let sheet=h.editor();const before=h.e.animation.animations.length;sheet.props.confirmation.content.props.request.actions[0].onPress();assert.equal(control(h.editor(),'Keep note').props.value,'Keep this draft');assert.equal(h.e.animation.animations.length,before);control(h.editor(),'Cancel Keep').props.onPress();sheet=h.editor();await sheet.props.confirmation.content.props.request.actions[1].onPress();h.e.unmount('draft');sheet=h.parent();assert.equal(sheet.type,'AddCardSheet');sheet.props.keepsContentMotion.onShow();assert.equal(h.e.animation.animations.at(-1).config.duration,140);assert.equal(h.e.files.size,0);h.close();
});
for(const option of ['Gallery','Camera'])test('M3-B '+option+' launches once before animation completes; pending/cancel/return keeps original safety',async()=>{
 const native=deferred(),h=addKeepHarness(e=>e.setPicker(native.promise));let chooser=h.parent();h.e.reduce(false);control(chooser,option).props.onPress();let sheet=h.editor();await flush();assert.equal(h.e.events.filter(v=>v[0]===option.toLowerCase()).length,1);sheet=h.editor();sheet.props.keepsContentMotion.onShow();const timing=h.e.animation.animations.at(-1);assert.equal(timing.config.duration,160);assert.equal(control(sheet,'Cancel Keep').props.disabled,true);sheet.props.onClose();h.e.animation.finish(timing);assert.equal(control(h.editor(),'Save Keep').props.disabled,true);assert.equal(h.e.files.size,0);native.resolve({canceled:true,assets:null});await flush();sheet=h.editor();sheet.props.keepsContentMotion.onShow();sheet.props.keepsContentMotion.onShow();assert.equal(h.e.events.filter(v=>v[0]===option.toLowerCase()).length,1);assert.equal(h.e.animation.animations.filter(a=>a.config.duration===160).length,1);assert.equal(control(sheet,'Cancel Keep').props.disabled,false);control(sheet,'Cancel Keep').props.onPress();h.e.unmount('draft');chooser=h.parent();chooser.props.keepsContentMotion.onShow();assert.equal(h.e.animation.animations.at(-1).config.duration,140);h.close();
});
